class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        dp = [[float('inf')]*3 for _ in range(n)]

        # Initialize the first row
        for j in range(3):
            dp[0][j] = cost[0][j]

        # Fill the DP table
        for i in range(1, n):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][j] = min(dp[i][j], dp[i-1][k] + cost[i][j])

        # The result is the minimum cost of painting the last house
        return min(dp[-1])

