class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = 0

        for i in range(n):
            good = True

            # Check if there's an index i-k
            if i - k >= 0:
                good &= nums[i] > nums[i - k]

            # Check if there's an index i+k
            if i + k < n:
                good &= nums[i] > nums[i + k]

            if good:
                res += nums[i]

        return res

