def count_kagamimochis(N, A):
    # Sort the list of mochis in ascending order
    A.sort()

    # Initialize a dictionary to store the frequency of each size of mochi
    freq = {}

    # Count the frequency of each size of mochi
    for size in A:
        if size in freq:
            freq[size] += 1
        else:
            freq[size] = 1

    # Calculate the number of different kinds of kagamimochi
    num_kagamimochis = 0

    # Iterate over each pair of mochis
    for i in range(N):
        for j in range(i + 1, N):
            # Check if the current pair can form a kagamimochi
            if A[i] <= A[j] / 2:
                # Add the frequency of the smaller size to the total number of kagamimochis
                num_kagamimochis += min(freq[A[i]], freq[A[j]])

    return num_kagamimochis

