class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if n < k:
            return False

        for i in range(n - k + 1):
            char_set = set()
            for j in range(i, i + k):
                if s[j] in char_set:
                    break
                char_set.add(s[j])
            else:
                return True

        return False

