class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Initialize the mentions list with zeros
        mentions = [0] * numberOfUsers

        # Dictionary to store mentions for each user
        user_mentions = defaultdict(set)

        # Dictionary to track user statuses
        user_status = {i: True for i in range(numberOfUsers)}

        # Process each event
        for event_type, timestamp, mentions_str in events:
            if event_type == "MESSAGE":
                # Update mentions for each user mentioned
                for user_id in map(int, mentions_str.split()):
                    user_mentions[user_id].add(timestamp)
                    mentions[user_id] += 1
            elif event_type == "OFFLINE":
                # Mark the user as offline
                user_status[int(mentions_str)] = False
                # Update mentions for all users who were online at the time
                for user_id in user_mentions[int(mentions_str)]:
                    mentions[user_id] -= 1

        return mentions

